pairs.push(...[["← رجوع لوحدات الصف", "← Back to year units"], ["نشوف، نلعب، ونجرب!", "Look, play and try!"], ["وقت صغير مع بعض، من غير مؤقّت ولا درجات للخط أو الكلام.", "A little time together, without timers or grades for handwriting or speaking."], ["نختار نشاطًا", "Choose an activity"], ["الصور والكلمات", "Pictures and words"], ["اسمع واختار", "Listen and choose"], ["الحروف والتتبّع", "Letters and tracing"], ["العدد واللون والشكل", "Number, colour and shape"], ["نقول ونمثّل", "Say and act"], ["وقت الحكاية", "Story time"], ["نلوّن", "Colouring"], ["نختار صورة التحية", "Choose a greeting picture"], ["أول حرف: T و I", "First letter: T and I"], ["المس الصورة: عربي ثم إنجليزي", "Tap a picture: Arabic, then English"], ["اسمع المعنى بالعربي الأول، وبعده الكلمة بالإنجليزي. تقدر تلمس صورة تانية في أي وقت.", "Hear the meaning in Arabic first, then the English word. You can tap another picture at any time."], ["أنشطة الوحدة والتقييمات", "Unit activities and assessments"], ["كل محطة بتصحح فورًا بعد كل سؤال.", "Each station gives feedback after every question."], ["خلّصت الوحدة!", "Unit complete!"], ["أول مقابلة.", "First meeting."], ["قولها بطريقتك.", "Say it your way."], ["محتاج تمارس مع حد؟", "Need someone to practise with?"], ["اسأل مستر باسم عن تدريب محادثة مناسب لهدفك.", "Ask Mr. Basem about conversation practice that fits your goal."], ["قول اسمك وبلدك وشغلك، واسأل الشخص اللي قدامك عن نفسه. وقت مقترح: 20 إلى 30 دقيقة.", "Say your name, country and job, and ask the other person about themselves. Suggested time: 20 to 30 minutes."], ["بدّل الرد بشخصية خيالية، وجرّب تقول الحوار بصوتك. مفيش تسجيل.", "Answer as an imaginary character and try saying the dialogue aloud. Nothing is recorded."]]);
pairs.push(...[["النشاط السابق", "Previous activity"], ["النشاط التالي", "Next activity"], ["لولي الأمر", "For the parent or carer"], ["جرّبنا النشاط مع بعض", "We tried this activity together"], ["🔊 عربي ثم إنجليزي", "🔊 Arabic, then English"], ["عربي الأول، وبعده إنجليزي", "Arabic first, then English"], ["جزء من الوحدة الأولى", "Part of Unit 1"], ["نسمع، نلعب، ونتتبّع!", "Listen, play and trace!"], ["نسمع ونقلّد الحركة", "Listen and copy the action"], ["اسمع المطلوب بالعربي", "Hear the instruction in Arabic"], ["اسمع المطلوب بالإنجليزي", "Hear the instruction in English"], ["للشخص الكبير: حدود الجزء المتاح", "For the adult: what is available"], ["وقت صغير مع شخص كبير. نشوف الصورة ونسمعها، ونجرّب الحركة سوا.", "A little time with an adult. Look at the picture, listen and try the action together."], ["القصة وأنشطة الصور والتتبع متاحة، ومعاها صفحة ألعاب وتدريبات أصلية جديدة. مفيش مؤقّت ولا درجات للخط أو الكلام.", "The story, picture activities and tracing are available, along with a new page of original games and practice. There are no timers or grades for handwriting or speaking."], ["اضغط على كل صورة واسمع الكلمة ورددها مع طفلك وقلّد الحركة. مفيش اختبار هنا.", "Tap each picture, listen to the word, repeat it with your child and copy the action. This is not a test."], ["بصّوا على الصور مع بعض، واربطوا كل صورة بالكلمة المكتوبة. ده نشاط بصري، مش درس نطق مسموع.", "Look at the pictures together and match each picture to the written word. This is a visual activity, not an audio pronunciation lesson."], ["دي متابعة للمحاولة على الجهاز ده، مش تقييم لنطق الطفل أو لجودة خطه. مفيش صور أو تسجيلات بتترفع.", "This tracks attempts on this device, not the child's pronunciation or handwriting quality. No pictures or recordings are uploaded."], ["أنشطة من كتاب الوزارة، مع صور وصوت وتدريب سماع أصلي للموقع. مفيش امتحان رسمي أو تقييم آلي للنطق والخط.", "Activities from the Ministry textbook, with original pictures, audio and listening practice for this site. There is no official exam or automated assessment of pronunciation or handwriting."], ["موضوعات من الوحدة الأولى بكتاب الوزارة، مع رسوم وأنشطة أصلية للموقع. اسمعوا الكلمات والجمل كاملة، مش أصوات حروف منفصلة. تتبع الإصبع تدريب حر من غير تصحيح آلي أو درجات. القصة وصورتا اللعب والعصير متاحة. تمرين الصح والخطأ والتقييم لسه غير متاحين هنا.", "Topics from Unit 1 of the Ministry textbook, with original illustrations and activities for the site. Listen to whole words and sentences, not individual letter sounds. Finger tracing is free practice without automated marking or grades. The story and the play and juice pictures are available. The true-or-false exercise and assessment are not available here yet."], ["أعلى نتيجة في كل صف. ولو فيه تعادل، الأسماء بتظهر سوا.", "The highest score in each year. Tied names appear together."], ["الثالث الإعدادي", "Preparatory 3"], ["الثاني الإعدادي", "Preparatory 2"], ["الثالث الابتدائي", "Primary 3"], ["الثاني الابتدائي", "Primary 2"], ["رجوع لصفحة الصف", "Back to the year page"], ["اختر الإجابة الصحيحة", "Choose the correct answer"], ["اكتب التصريف الصحيح", "Write the correct form"], ["أكمل الفراغ", "Fill the gap"], ["رتّب الكلمات وكوّن الجملة", "Order the words to make a sentence"], ["ابدأ بتقدير مستواك، حدد هدفك من الإنجليزي، وشوف خطتك المقترحة. أول وحدة A1 متاحة الآن. إصدار أولي بيتطوّر.", "Start with an estimate of your level, choose your English goal and see your suggested plan. The first A1 unit is available now. An early version, still developing."]]);
pairs.push(...[["افهم الفكرة، مش الإجابة بس.", "Understand the idea, not only the answer."], ["اكتب سؤالك في الإنجليزي أو اختار موضوع، وخد شرح يناسب سنتك بأمثلة بسيطة. والدروس الجاهزة موجودة تحت.", "Ask an English question or choose a topic for an explanation at your level with simple examples. Ready-to-use lessons are below."], ["شرح يناسب خطوتك", "An explanation at your level"], ["بالذكاء الاصطناعي · من غير حساب ولا تسجيل · وبيانات الطلبة مش بتتخزّن عندنا", "AI-assisted · No account or sign-up · We do not store student data"], ["سنتك الدراسية", "Your school year"], ["موضوع التعلّم", "Learning topic"], ["سؤالك في الإنجليزي (اختياري)", "Your English question (optional)"], ["لا تكتب اسمك أو أسماء طلاب أو أرقامًا أو عناوين أو أي بيانات شخصية. لو أقل من 18 سنة، استخدم الأداة مع ولي أمرك. لا يوجد تسجيل دخول.", "Do not enter your name, student names, numbers, addresses or personal details. If you are under 18, use this tool with a parent or guardian. No sign-in is required."], ["اشرح لي ↖", "Explain it to me ↖"], ["اختار سنتك وابدأ. الإجابة قد تخطئ، فراجعها مع المدرّس.", "Choose your school year to start. Answers can be wrong, so check them with your teacher."], ["الشرح والأسئلة تدريب عام مناسب للمستوى، وليسا نقلًا أو اعتمادًا لكتاب الوزارة أو لوحدة دراسية محددة. الخدمة المجانية لها حد يومي مشترك، وقد تتوقف لحد ما يتجدد.", "The explanations and questions are general practice at your level, not a reproduction or endorsement of the Ministry textbook or a specific unit. The free service has a shared daily limit and may pause until it resets."], ["صوّر السؤال 📷", "Photograph the question 📷"], ["صوّر سؤال إنجليزي أو كلمات من كتاب الوزارة، والمساعد يحلّها أو يترجمها ويشرحها بالعربي · من غير ما تكتب حاجة", "Photograph an English question or words from the Ministry textbook. The assistant can answer or translate them and explain in Arabic, without typing."], ["صورة السؤال", "Question photo"], ["ملاحظة (اختياري)", "Note (optional)"], ["صوّر السؤال بس، من غير أسماء أو صور أشخاص. الصورة بتتبعت للمعالجة لحظيًا ومش بتتخزّن عندنا.", "Photograph only the question, without names or pictures of people. The image is sent for immediate processing and is not stored by us."], ["حلّل الصورة ↖", "Analyze the image ↖"], ["صوّر السؤال واضح وفي ضوء كويس. الإجابة قد تخطئ، فراجعها مع المدرّس.", "Take a clear photo in good light. Answers can be wrong, so check them with your teacher."], ["ابدأ بسؤال واضح", "Start with a clear question"], ["نتعلّم إيه النهارده؟", "What shall we learn today?"], ["اختار درس وشوف شرحه الجاهز على جهازك، من غير ما تبعت أي بيانات.", "Choose a lesson and read its explanation on your device, without sending any data."], ["شرح محلي", "On-device explanation"], ["أهلًا بيك. نبدأ نفهم سوا.", "Welcome. Let's work through it together."], ["اختار درس من القائمة، واقرا القاعدة وجرّب المثال بنفسك.", "Choose a lesson from the list, read the rule and try the example yourself."], ["اسمع الشرح", "Listen to the explanation"], ["بداية جديدة", "Start again"], ["النطق بيستخدم صوت المتصفح لو متاح. الصوت واللغات بيختلفوا من جهاز للتاني، وممكن يعتمدوا على خدمة النظام.", "Speech uses the browser voice when available. Voices and languages vary by device and may depend on a system service."], ["الصف 1 الابتدائي", "Primary 1"], ["الصف 2 الابتدائي", "Primary 2"], ["الصف 3 الابتدائي", "Primary 3"], ["الصف 4 الابتدائي", "Primary 4"], ["الصف 5 الابتدائي", "Primary 5"], ["الصف 6 الابتدائي", "Primary 6"], ["الصف 1 الإعدادي", "Preparatory 1"], ["الصف 2 الإعدادي", "Preparatory 2"], ["الصف 3 الإعدادي", "Preparatory 3"], ["الصف 1 الثانوي", "Secondary 1"], ["الصف 2 الثانوي", "Secondary 2"], ["الصف 3 الثانوي", "Secondary 3"]]);
pairs.push(...[["الحروف والأصوات", "Letters and sounds"], ["مفردات يومية", "Everyday vocabulary"], ["المضارع البسيط", "Present simple"], ["المضارع المستمر", "Present continuous"], ["الماضي البسيط", "Past simple"], ["التعبير عن المستقبل", "Talking about the future"], ["أدوات الاستفهام", "Question words"], ["حروف الجر", "Prepositions"], ["المقارنة والتفضيل", "Comparatives and superlatives"], ["فهم المقروء", "Reading comprehension"], ["كتابة فقرة قصيرة", "Writing a short paragraph"], ["مراجعة عامة", "General revision"], ["كبار من الصفر", "Adults starting from scratch"], ["مثال: إيه الفرق بين do و does؟ سيبه فاضي لو عايز شرح الموضوع اللي اخترته.", "Example: What is the difference between do and does? Leave this blank for an explanation of your chosen topic."], ["مثال: عايز معنى الكلمات دي بس", "Example: I only want the meanings of these words"]]);
pairs.push(...[["طريق واضح، من أول خطوة.", "A clear path from your first step."], ["اختار مرحلتك، وكلّم مستر عشان تعرف المجموعات والمواعيد. مفيش حجز أو دفع على الموقع.", "Choose your stage and contact your teacher about groups and times. There is no booking or payment on this site."], ["مش متأكد تبدأ منين؟", "Not sure where to start?"], ["المرحلة مش هي المستوى كله.", "Your school stage does not tell the whole story."], ["قولّي عايز توصل لإيه وبدأت قبل كده ولا لأ، ونختار البداية المناسبة. كل واحد ليه وقته وخطواته.", "Tell me your goal and whether you have studied before, and we can choose a suitable starting point. Everyone has their own pace."], ["اسأل عن المسار المناسب ↗", "Ask about the right path ↗"], ["جرّب تدريب قصير", "Try a short practice"], ["مقالات تعلّم الإنجليزي", "English learning articles"], ["ARTICLES / مقالات", "ARTICLES"], ["مقالات تعلّم الإنجليزي.", "English learning articles."], ["مقالات قصيرة بالعربي عن تعلّم الإنجليزي: ليه مهمة في الشغل والدراسة، وإزاي تتعلمها صح. مقالات جديدة بتنزل باستمرار.", "Short articles in Arabic about learning English: why it matters for work and study, and how to learn it well. New articles are added regularly."], ["ليه الإنجليزي بيفتحلك أبواب في حياتك المهنية؟", "How can English open doors in your career?"], ["فرص أكبر، مرتبات أعلى، وإنترفيوهات بتعديها بثقة.", "More opportunities, higher pay and interviews you can approach with confidence."], ["اقرأ المقال ↗", "Read the article ↗"], ["أهمية الإنجليزي في الدراسة والحياة العلمية", "Why English matters for study and academic life"], ["الوصول للمعرفة من مصدرها، من المدرسة للجامعة للبحث.", "Access knowledge at its source, from school to university and research."], ["الإنجليزي في كل مجال: تكنولوجيا، طب، سياحة، وأكتر", "English in every field: technology, medicine, tourism and more"], ["إزاي الإنجليزي بتضاعف قيمة مهاراتك في أي مجال.", "How English can add value to your skills in any field."], ["إزاي تذاكر إنجليزي لوحدك من غير كورسات؟", "How can you study English on your own without courses?"], ["خطة يومية بسيطة ومصادر مجانية تبدأ بيها فورًا.", "A simple daily plan and free resources to start using now."], ["أشهر أخطاء المصريين في الإنجليزي", "Common English mistakes made by Egyptian learners"], ["غلطات صغيرة متكررة، وتصحيحها وسببها.", "Common small mistakes, their corrections and the reasons behind them."], ["عندك سؤال عن تعلّم الإنجليزي؟", "Have a question about learning English?"], ["ابعتله على واتساب، وممكن يبقى موضوع المقال الجاي.", "Send it on WhatsApp. It could become the next article topic."], ["كلّم مستر باسم", "Contact Mr. Basem"], ["المفرد والجمع", "Singular and plural"], ["٦ وحدات + مراجعتين من كتاب الوزارة، أنشطة تفاعلية بتصحيح فوري بعد كل سؤال.", "6 units and 2 revisions from the Ministry textbook, with interactive activities and instant feedback after each question."]]);
pairs.push(["اسأل عن المسار المناسب","Ask about the right path"],["اقرأ المقال","Read the article"]);
pairs.push(["اسأل عن المسار المناسب ↖","Ask about the right path ↖"],["اقرأ المقال ↖","Read the article ↖"]);
pairs.push(...[["32 سؤالًا أصليًا في القراءة واستخدام اللغة: 8 أسئلة في كل حزمة من A1 إلى B2. النتيجة نقطة بداية استرشادية غير معايرة على CEFR، مش شهادة أو تقييمًا شاملًا. مفيش منح آلي لـC1 أو C2. الاستماع والمحادثة والكتابة محتاجين تقييمًا منفصلًا مع مدرس.", "32 original reading and language-use questions: 8 questions in each group from A1 to B2. The result is a suggested starting point, not calibrated to CEFR, a certificate or a full assessment. It does not automatically award C1 or C2. Listening, speaking and writing need a separate assessment with a teacher."], ["جرّب، وافهم السبب.", "Try it and understand why."], ["اللغة من عندك", "Use your own words"], ["شوف مثالًا للمقارنة", "See an example to compare"], ["دي مهمة للمقارنة الذاتية، مش كتابة بيتم تصحيحها آليًا. جرب تقولها بصوتك كمان، من غير تسجيل أو إرسال. استخدم شخصية خيالية لو تحب.", "This is a self-comparison task, not automatically marked writing. Try saying it aloud too, without recording or sending it. You can use a fictional person."], ["من التدريب للمحادثة", "From practice to conversation"]]);
pairs.push(...[["بيانات أقل. راحة أكتر.", "Less data. More peace of mind."], ["اعرف إيه اللي بيتحفظ على جهازك وإيه اللي بيتبعت للخدمات.", "See what stays on your device and what is sent to services."], ["بدون حساب طالب", "No student account"], ["مش محتاج تعمل حساب أو تدخل كلمة سر. اسم البحث ورقم تليفونك مش بيتجمعوا. النتائج العامة بيضيفها مستر بعد إذن مناسب. مفيش هنا حجز بيبعت بيانات لخادم، ولا إعلانات أو أدوات تحليل مضافة.", "You do not need an account or password. Search names and your phone number are not collected. Your teacher adds public results after obtaining appropriate permission. There is no booking form that sends data to a server, and no added advertising or analytics tools."], ["الحفظ على جهازك", "Storage on your device"], ["المتصفح بيحفظ اختيارك لشكل الموقع وآخر نتائج تدريبك بس، مش اسمك ولا إجاباتك المكتوبة. تقدر تمسح السجل من صفحة النتائج أو إعدادات المتصفح. لو الجهاز مشترك، امسح السجل لما تخلص.", "The browser stores your appearance preference and recent practice results, not your name or written answers. You can clear the history on the results page or in browser settings. On a shared device, clear it when you finish."], ["النصوص والبيانات الشخصية", "Text and personal data"], ["لا تكتب أي أسماء أو بيانات شخصية، وخاصة بيانات الأطفال. يوجد فحص آلي لرفض بعض البيانات الواضحة قبل الإرسال وقبل تمرير النص للنموذج، لكنه ليس ضمانًا لاكتشاف كل اسم أو معلومة تعريفية. استخدم نصوصًا دراسية عامة فقط. للصغار، يُنصح بالاستخدام مع ولي الأمر، دون حساب أو بوابة تسجيل.", "Do not enter names or personal data, especially children's data. An automated check rejects some obvious personal data before sending and before passing text to the model, but it cannot guarantee detection of every name or identifying detail. Use general study text only. Younger learners should use the tools with a parent or guardian, without an account or sign-in portal."], ["أدوات الذكاء الاصطناعي", "AI tools"], ["عند طلب شرح أو ترجمة أو أسئلة، تُرسل اختيارات السنة والموضوع، وأي سؤال أو نص دراسي تكتبه، إلى خدمة Cloudflare Workers AI. أدوات النص تستخدم نماذج Qwen وLlama وMistral لدى الخدمة، بحسب نوع الطلب. بعض القواعد الأساسية لها شرح ثابت مُراجع ومميّز بوضوح بدل التوليد. عند اختيار حل سؤال بصورة، تُرسل الصورة المختارة والنص المصاحب إلى نموذج رؤية لدى الخدمة، فلا ترفع صور أشخاص أو أوراقًا فيها أسماء أو درجات أو بيانات شخصية. في ممارسة الكبار الاختيارية، وبعد الموافقة داخل الصفحة، يُرسل المستوى والهدف والمجال المختار وآخر جزء من المحادثة ليستمر التدريب في نفس السياق. المحادثة تبقى في ذاكرة الصفحة أثناء فتحها، ولا ينشئ الموقع لها سجلًا دائمًا. لا يوجد حساب طالب أو قاعدة بيانات للمستخدمين، ولا نحفظ محتوى الطلبات أو الردود على خادم الموقع. لا نرسل إجابات التدريب الجاهز للتصحيح، فهو يتم في المتصفح. الخدمة ليست معتمدة من وزارة التعليم، وقد تخطئ الإجابات والشرح أو تربط السؤال بالمنهج بشكل غير دقيق.", "When you request an explanation, translation or questions, your school-year and topic choices, plus any question or study text you enter, are sent to Cloudflare Workers AI. The text tools use its Qwen, Llama and Mistral models, depending on the request. Some basic rules have clearly marked, reviewed fixed explanations instead of generated ones. For photo questions, the selected image and accompanying text are sent to a vision model at the service. Do not upload pictures of people or pages containing names, grades or personal data. In optional adult practice, after consent within the page, the level, goal, chosen field and latest part of the conversation are sent to keep the practice in context. The conversation stays in page memory while the page is open; the site does not create a permanent conversation record. There is no student account or user database, and we do not store request or response content on the site's server. Ready-made practice answers are marked in the browser and are not sent for marking. The service is not endorsed by the Ministry of Education. Answers and explanations may be wrong or may link a question to the curriculum incorrectly."], ["النطق والروابط الخارجية", "Speech and external links"], ["تُحمّل الخطوط من Google Fonts. زر النطق يستخدم المتصفح ونظام الجهاز، وقد تعالج خدمة الصوت النص عند الطلب. روابط واتساب وإنستجرام تفتح خدمات خارجية. GitHub وCloudflare وGoogle قد تعالج بيانات تقنية مثل عنوان IP وبيانات الأمان لتقديم خدماتها. Cloudflare تقول إنها لا تستخدم محتوى Workers AI لتدريب النماذج، ومعالجة الطلبات العادية لا تحتفظ بالمدخلات والمخرجات بعد تقديم الرد، مع الاستثناءات القانونية والبيانات التشغيلية الواردة في سياستها. لا يعني عدم وجود قاعدة بيانات أن مزودي الاستضافة لا يعالجون أي بيانات تقنية.", "Fonts load from Google Fonts. The speech button uses the browser and device system; a speech service may process the text on request. WhatsApp and Instagram links open external services. GitHub, Cloudflare and Google may process technical data such as IP addresses and security data to provide their services. Cloudflare states that it does not use Workers AI content to train models and that ordinary request processing does not retain inputs and outputs after the response, subject to the legal exceptions and operational data described in its policy. Having no database does not mean hosting providers process no technical data."], ["النتائج والصور", "Results and photos"], ["لوحة الشرف والنتائج متاحة لأي حد، وملف البيانات كامل ممكن يتقري. البحث بالاسم والصف بيشتغل جوه متصفحك، ومش بوابة خاصة للدرجات. مستر بيضيف الأسماء والدرجات والصور بعد الإذن المناسب. متضيفش أرقام تليفونات أو هويات أو بيانات خاصة. النتائج الموجودة مستر بعتها عشان تتضاف للموقع.", "The honor board and results are available to anyone, and the full data file can be read. Name and grade search runs inside your browser; this is not a private grades portal. Your teacher adds names, grades and photos after obtaining appropriate permission. Do not add phone numbers, identity documents or private data. The teacher supplied the existing results for inclusion on the site."], ["تواصل", "Contact"], ["لو عندك سؤال، كلّم MR. BASEM HREAZ على واتساب.", "For questions, contact MR. BASEM HREAZ on WhatsApp."], ["المزودون والحد المجاني", "Providers and the free limit"], ["الخدمة على الخطة المجانية فقط، وقد تتوقف الطلبات عند بلوغ الحد اليومي المشترك أو ضغط الاستخدام. لا توجد مدفوعات على الزائر.", "The service uses the free plan only. Requests may stop when the shared daily limit is reached or demand is high. Visitors do not pay."], ["سياسة بيانات Workers AI", "Workers AI data policy"], ["قواعد استخدام نموذج Qwen", "Qwen model usage rules"]]);
pairs.push(...[["امتحانات ومذكرات انجليزي PDF لكل الصفوف", "English exams and PDF study notes for all grades"], ["امتحانات ومذكرات إنجليزي. كل ورقة، لها هدف.", "English exams and study notes. Every sheet has a purpose."], ["مذكرات وامتحانات إنجليزي لكل المراحل، بتتجدد لوحدها كل ساعة.", "English study notes and exams for all stages, refreshed automatically every hour."], ["موارد إنجليزي بتتجدّد لوحدها", "English resources that refresh automatically"], ["مذكرات ومراجعات وامتحانات إنجليزي مختارة من قنوات تليجرام تعليمية، لكل الصفوف. كل رابط يودّيك لصفحة المصدر تحمّل منها الملف، والقايمة بتتحدّث أوتوماتيك كل ساعة.", "English study notes, revisions and exams selected from educational Telegram channels for all grades. Each link opens the source page where you can download the file. The list updates automatically every hour."], ["الكل", "All"], ["ابتدائي", "Primary"], ["إعدادي", "Preparatory"], ["ثانوي", "Secondary"], ["حصلت مشكلة في تحميل الموارد. جرّب تاني بعد شوية.", "The resources could not load. Try again later."], ["لحد ما مكتبتك تكتمل…", "While your library grows..."], ["تقدر تتدرّب دلوقتي على أسئلة قصيرة وتراجع تفسير كل إجابة.", "Practise with short questions now and review the explanation for each answer."], ["ابدأ التدريب المجاني ↖", "Start free practice ↖"], ["ابدأ التدريب المجاني ↗", "Start free practice ↗"], ["نتائج الامتحانات والأوائل", "Exam results and top students"], ["النتائج والأوائل", "Results and top students"], ["نتائج نفتخر بيها. وتقدّم نكمّله.", "Results to be proud of. Progress to build on."], ["لوحة شرف ونتائج منشورة باختيار مستر، مع سجل تدريبك الشخصي المنفصل.", "An honor board and results selected by your teacher, separate from your personal practice history."], ["أعلى 3 طلاب في كل صف، ومعاهم أي حد متعادل عند درجة الطالب التالت.", "The top 3 students in each grade, including anyone tied with the third student's score."], ["تعب يستحق نفرح بيه", "Hard work worth celebrating"], ["ابحث عن نتيجتك", "Find your result"], ["النتائج هنا متاحة لأي حد، مش بوابة خاصة. هتلاقي النتائج اللي مستر نشرها بإذن مناسب بس. مش محتاج كود أو رقم سري، والاسم اللي بتبحث بيه مش بيتبعت لخادم.", "These results are available to anyone, not behind a private portal. Only results published by your teacher with appropriate permission appear here. No code or password is needed, and the name you search for is not sent to a server."], ["اسم الطالب", "Student name"], ["الصف", "Grade"], ["كل المراحل", "All stages"], ["هتظهر درجة طالب واحد بس، من غير ترتيب أو مقارنة.", "Only one student's score will appear, without a ranking or comparison."], ["اكتب اسمك، واختار الصف لو فيه تشابه أسماء.", "Enter your name and choose your grade if names are similar."], ["التدريب الشخصي", "Personal practice"], ["آخر محاولاتك", "Your recent attempts"], ["نتائج تدريبك بتتحفظ على المتصفح ده بس، من غير اسم أو رقم تليفون.", "Your practice results are stored only in this browser, without a name or phone number."], ["لسه مفيش محاولات محفوظة. ابدأ أول تدريب.", "No attempts saved yet. Start your first practice."], ["امسح سجل هذا الجهاز", "Clear this device's history"], ["نفس ترتيب الوحدات، والجزء الجاهز بس هو اللي تقدر تفتحه. أنشطة مناسبة لسن الطفل، من غير درجات للخط أو النطق.", "The units keep the same order. Only ready sections can be opened. Activities suit the child's age, without handwriting or pronunciation scores."], ["افتح الأنشطة والتدريبات", "Open activities and practice"], ["م١", "I1"], ["م٢", "I2"], ["الأول المتوسط · Super Goal 1", "Intermediate 1 · Super Goal 1"], ["الثاني المتوسط · Super Goal 2", "Intermediate 2 · Super Goal 2"], ["أولى متوسط · الجزء الأول جاهز", "Intermediate 1 · Part 1 ready"], ["Intermediate 2 · الجزء الأول جاهز", "Intermediate 2 · Part 1 ready"]]);
pairs.push(["الجزء الأول جاهز","Part 1 ready"]);
pairs.push(...[["اكتب الاسم أو اسأل عن الدرجة", "Enter a name or ask about the score"], ["ممكن الاسم التاني أو الثلاثي؟", "Could you enter the second or third name?"], ["ممكن تحدد الصف؟", "Could you choose the grade?"], ["مش لاقي الاسم ده، ممكن تكتبه أوضح أو تقولي الصف؟", "That name was not found. Could you enter it more clearly or choose the grade?"], ["اللوحة مش راضية تفتح. جرّب تحدّث الصفحة.", "The board could not load. Try refreshing the page."], ["كل المناهج السعودية", "All Saudi curricula"], ["نسخة الكتاب التي راجعناها على شواهد (موقع مستقل)", "The book copy reviewed on Shwahed, an independent site"], ["للنسخة الرسمية والمقررات الرقمية، ابدأ من خدمة التعليم الإلكتروني لدى وزارة التعليم.", "For official copies and digital courses, start with the Ministry of Education's e-learning service."], ["دليل وزارة التعليم للكتب عبر مدرستي", "Ministry of Education guide to books on Madrasati"], ["للنسخة الرسمية والمقررات الرقمية، ابدأ من خدمة التعليم الإلكتروني لدى وزارة التعليم. يتضمن دليل الوزارة طريقة الوصول إلى الكتب عبر مدرستي. تعذر التحقق من الرابط المباشر للكتاب على عين وقت المراجعة.", "For official copies and digital courses, start with the Ministry of Education's e-learning service. The Ministry's guide explains how to access books on Madrasati. The direct book link on Ain could not be verified at the time of review."], ["نسخة الكتاب التي راجعناها على هلا سكول، موقع مستقل", "The book copy reviewed on Hala School, an independent site"], ["تعذر فتح رابط الكتاب على خادم عين وقت المراجعة، فراجعنا نسخة الكتاب ذات ختم الوزارة على المصدر المستقل. رابط المصدر فوق، والصفحات المتاحة موضحة بوضوح.", "The book link on Ain's server could not be opened at the time of review, so a copy carrying the Ministry's stamp was reviewed on the independent source. The source link is above, with the available pages clearly stated."], ["تعذر تحميل ملف الكتاب من خادم عين وقت المراجعة، فراجعنا نسخة الكتاب ذات ختم الوزارة على المصدر المستقل.", "The book file could not be downloaded from Ain's server at the time of review, so a copy carrying the Ministry's stamp was reviewed on the independent source."], ["الجزء الأول جاهز كاملًا: الوحدات 1–8 ومراجعتان، بإجمالي 574 سؤالًا تفاعليًا. الجزء الثاني من الكتاب لسه مش جاهز.", "Part 1 is ready in full: units 1-8 and 2 revisions, with 574 interactive questions. Part 2 of the book is not ready yet."], ["الجزء الأول كامل جاهز: الوحدات 1–8 والمراجعتان، 468 سؤالًا تفاعليًا. الجزء الثاني من الكتاب، الوحدات 9–16 ومراجعاتها، لسه مش منشورين.", "Part 1 is ready in full: units 1-8 and 2 revisions, with 468 interactive questions. Part 2, units 9-16 and their revisions, is not published yet."], ["المرجع: Super Goal 1، الجزء الأول، وزارة التعليم السعودية، ختم 2026 / 1448. راجعنا الوحدات 1–8 والمراجعتين في الصفحات 2–77. الشرح والأسئلة هنا أصلية من إعداد ENGLISH SAVANT، وليست نقلًا لأسئلة الكتاب.", "Reference: Super Goal 1, Part 1, Saudi Ministry of Education, stamped 2026 / 1448. Units 1-8 and both revisions on pages 2-77 were reviewed. The explanations and questions here are original ENGLISH SAVANT work, not copies of the book's questions."], ["المرجع: Super Goal 2، الجزء الأول، وزارة التعليم السعودية، ختم 2026 / 1448. راجعنا الجزء الأول كاملًا: الوحدات 1–8 ومراجعتي الوحدات 1–4 و5–8 في الصفحات 2–77. الشرح والأسئلة هنا أصلية من إعداد ENGLISH SAVANT، وليست نقلًا لأسئلة الكتاب.", "Reference: Super Goal 2, Part 1, Saudi Ministry of Education, stamped 2026 / 1448. All of Part 1 was reviewed: units 1-8 and revisions for units 1-4 and 5-8 on pages 2-77. The explanations and questions here are original ENGLISH SAVANT work, not copies of the book's questions."], ["متاح في التهيئة ٧ أنشطة: كلمات بالصور والصوت، ولعبة الشنطة، وتمثيل مع شخص كبير، وتتبع الأشكال. بعض جمل الصوت لسه بتتجهز.", "7 warm-up activities are available: picture and audio vocabulary, a bag game, role-play with an adult and shape tracing. Some spoken sentences are still being prepared."], ["افتح أنشطة التهيئة", "Open warm-up activities"], ["٨ أنشطة بالصور والصوت، ومنها قصة الحركات وتتبع الحروف والأعداد، ومعاها ١٠ ألعاب أصلية مع شخص كبير من غير درجات.", "8 picture and audio activities, including an action story and letter and number tracing, plus 10 original games with an adult and no scores."], ["٧ أنشطة متاحة، ومنها قصة الهدوم بالصور وجمل إنجليزية ومعاني مكتوبة بالمصري. باقي المحتوى لسه بيتجهز.", "7 activities are available, including a picture story about clothes, English sentences and meanings written in Egyptian Arabic. Remaining content is still being prepared."], ["فيديو الشرح بالعربي متاح، ومعاه أنشطة الصور والصوت وألعاب التدريب مع شخص كبير.", "The Arabic explanation video is available, with picture and audio activities and practice games to play with an adult."], ["7 أنشطة متاحة من الجزء ده، بالصور والصوت والتجربة مع شخص كبير. باقي المحتوى لسه بيتجهز.", "7 activities from this section are available, with pictures, audio and practice with an adult. Remaining content is still being prepared."], ["٦ وحدات + مراجعتين من كتاب الوزارة. لكل وحدة صفحة شرح وبطاقات تفاعلية وتدريبات قصيرة منفصلة.", "6 units and 2 revisions from the Ministry book. Each unit has an explanation page, interactive cards and separate short practice activities."]]);
pairs.push(...[["مفيش موارد للمرحلة دي لسه.", "No resources for this stage yet."], ["لسه مفيش موارد متضافة — أول تحديث قريب إن شاء الله.", "No resources have been added yet. The first update is coming soon."], ["جاري تحميل الموارد…", "Loading resources..."], ["فتح المصدر ↗", "Open source ↗"], ["فتح المصدر ↖", "Open source ↖"]]);
pairs.push(...[["مذكرات وامتحانات إنجليزي لكل المراحل. التحديث مجدول كل ساعة، وممكن يتأخر.", "English study notes and exams for all stages. Updates are scheduled hourly and may be delayed."], ["موارد إنجليزي بتتحدّث تلقائيًا", "English resources updated automatically"], ["مذكرات ومراجعات وامتحانات إنجليزي مختارة من قنوات تليجرام تعليمية، لكل الصفوف. كل رابط يودّيك لصفحة المصدر تحمّل منها الملف. تحديث القايمة مجدول كل ساعة، وممكن يتأخر.", "English study notes, revisions and exams selected from educational Telegram channels for all grades. Each link opens the source page where you can download the file. List updates are scheduled hourly and may be delayed."], ["8 أنشطة متاحة. صور الكلمات وأمثلة الحروف المتاحة بتبدأ بالعربي وبعده الإنجليزي، ومعاها تدريب اسمع واختار الصورة وأنشطة أصلية. السرد الصوتي متاح لقصص الوحدات ١–٤. مفيش تقييم آلي للنطق أو الخط.", "8 activities available. Available word pictures and letter examples play Arabic before English, with listen-and-choose-picture practice and original activities. Story narration is available for Units 1-4. There is no automatic pronunciation or handwriting assessment."], ["9 أنشطة متاحة. صور الكلمات وأمثلة الحروف المتاحة بتبدأ بالعربي وبعده الإنجليزي، ومعاها تدريب اسمع واختار الصورة وأنشطة أصلية. السرد الصوتي متاح لقصص الوحدات ١–٤. مفيش تقييم آلي للنطق أو الخط.", "9 activities available. Available word pictures and letter examples play Arabic before English, with listen-and-choose-picture practice and original activities. Story narration is available for Units 1-4. There is no automatic pronunciation or handwriting assessment."], ["10 أنشطة متاحة. صور الكلمات وأمثلة الحروف المتاحة بتبدأ بالعربي وبعده الإنجليزي، ومعاها تدريب اسمع واختار الصورة وأنشطة أصلية. السرد الصوتي متاح لقصص الوحدات ١–٤. مفيش تقييم آلي للنطق أو الخط.", "10 activities available. Available word pictures and letter examples play Arabic before English, with listen-and-choose-picture practice and original activities. Story narration is available for Units 1-4. There is no automatic pronunciation or handwriting assessment."], ["11 أنشطة متاحة. صور الكلمات وأمثلة الحروف المتاحة بتبدأ بالعربي وبعده الإنجليزي، ومعاها تدريب اسمع واختار الصورة وأنشطة أصلية. السرد الصوتي متاح لقصص الوحدات ١–٤. مفيش تقييم آلي للنطق أو الخط.", "11 activities available. Available word pictures and letter examples play Arabic before English, with listen-and-choose-picture practice and original activities. Story narration is available for Units 1-4. There is no automatic pronunciation or handwriting assessment."]]);
